[tool error]
{
  "ok": false,
  "name": "draw_station_offset",
  "error": {
    "type": "command_failed",
    "message": "cannot parse anchor '30+00@?': bad offset '?' (use 25, -25, 25L or 25R)",
    "hint": "anchor = BEGIN | END | PI-n | PC-n | PT-n | MC-n | T-n | EQ-n | '18+00.00' | 1800, optionally '@offset' (ft, right +; '25L' = 25 ft left), e.g. 'PC-1@16', '18+00@25L'; BC-n / EC-n are the same points as PC-n / PT-n; or {ref|station, offset, region}",
    "example": {
      "alignment": "SR-100",
      "points": [
        "30+00@12R",
        "31+20@24R",
        "36+00@24R",
        "36+00@12R"
      ],
      "layer": "V-ROAD-EOP"
    }
  },
  "warnings": []
}

[tool error]
{
  "ok": false,
  "name": "draw_station_offset",
  "error": {
    "type": "invalid_params",
    "message": "['36+00@12R'] is too short (at 'points')",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "model (the default; stations are model feet)"
        },
        "alignment": {
          "type": "string",
          "minLength": 1,
          "description": "the alignment the stations are on (default the only one)"
        },
        "points": {
          "type": "array",
          "items": {
            "type": [
              "string",
              "number",
              "object"
            ],
            "description": "BEGIN | END | PI-n | PC-n | PT-n | MC-n | T-n | EQ-n | '18+00.00' | 1800, optionally '@offset' (ft, right +, e.g. 'PC-1@16', '18+00@25L'); or {ref|station, offset, region}. BC-n and EC-n, as a Caltrans plan letters them, are PC-n and PT-n"
          },
          "minItems": 2,
          "description": "station-and-offset points in order: '30+00@12R', '31+20@24R', 'PC-1@12L', 'END@14R', {station, offset}"
        },
        "follow": {
          "type": "boolean",
          "description": "between two points at the same offset, follow the alignment (arcs on its curves, exactly as draw_offset) instead of a straight chord (default true); where the offset changes the run is a straight taper"
        },
        "polyline": {
          "type": "boolean",
          "description": "draw one polyline (curves as arc segments) instead of lines and arcs"
        },
        "close": {
          "type": "boolean",
          "description": "close back to the first point"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer name; defaults to the current layer"
        },
        "color": {
          "type": "string",
          "description": "override color; omit for ByLayer"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ],
          "description": "override linetype; omit for ByLayer"
        }
      },
      "required": [
        "points"
      ],
      "additionalProperties": false
    },
    "example": {
      "alignment": "SR-100",
      "points": [
        "30+00@12R",
        "31+20@24R",
        "36+00@24R",
        "36+00@12R"
      ],
      "layer": "V-ROAD-EOP"
    }
  },
  "warnings": []
}
